import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xid9')
from h import *
P=[]
P.append(R(3681,"Wortel Jeli Slow Cooker","Cobalah resep Wortel Jeli Slow Cooker yang mudah dan ramah ginjal ini.","6","1/2 cangkir",
["3 cangkir wortel segar","2 sendok makan dressing vinaigrette anggur merah","2 sendok makan jeli apel","1 sendok teh lada hitam","1 sendok teh campuran bumbu herba Mrs. Dash®"],
["Untuk menyiapkan wortel, kupas, belah dua memanjang, lalu potong setiap belahan menjadi 4 bagian. Masukkan ke dalam slow cooker.","Tambahkan dressing vinaigrette, jeli, lada hitam, dan bumbu herba. Aduk hingga wortel terlapisi.","Atur slow cooker pada api rendah, tutup dengan penutup, dan masak 3 sampai 4 jam hingga wortel empuk."],
["Gunakan wortel beku atau wortel baby utuh sebagai pengganti wortel mentah ukuran biasa. Tidak perlu dipotong."],
["1 sayuran","1/2 kalori tinggi"]))
P.append(R(3682,"Dada Ayam Asap dalam Wajan","Dada Ayam Asap dalam Wajan menggunakan wajan pengasap dapur buatan sendiri untuk meresapkan cita rasa asap yang lezat pada dada ayam yang dilumuri bumbu. Hidangan rendah natrium ini kaya cita rasa.","4","3 ons",
["1/2 sendok makan paprika","1/2 sendok teh ketumbar bubuk","1/2 sendok teh jinten bubuk","1/4 sendok teh cabai cayenne bubuk","1/4 sendok teh bubuk bawang putih","1/4 sendok teh thyme kering","4 dada ayam tanpa tulang dan tanpa kulit","4 sendok teh minyak kanola"],
["Campurkan rempah-rempah untuk membuat bumbu lumur.","Bilas dada ayam, keringkan, dan olesi tipis dengan minyak.","Lumuri dada ayam dengan campuran bumbu lumur.","Simpan dada ayam di lemari es selama 3 sampai 4 jam.","Panaskan oven terlebih dahulu hingga 400º F.","Untuk menyiapkan wajan pengasap, letakkan serpihan kayu keras dalam loyang foil sekali pakai dan letakkan rak di atasnya. Panaskan loyang di atas kompor dengan api sedang-besar hingga asap muncul. Letakkan dada ayam yang sudah dimarinasi di atas rak dan tutup loyang rapat-rapat dengan foil.","Kecilkan api ke sedang dan asapi dada ayam selama 10 menit.","Pindahkan dada ayam ke loyang pemanggang dan panggang dalam oven selama 10 menit."],
["Sajikan dengan nasi putih dan Tumis Sayuran.","Pilih dada ayam yang beratnya sekitar 4 ons per potong saat mentah.","Sesuaikan porsi dengan rencana makan Anda jika Anda menjalani diet protein yang lebih rendah atau lebih tinggi."],
["3 daging"]))
P.append(R(3686,"Gulung Crepe Asparagus dan Keju dengan Peterseli","Sajikan Gulung Crepe Asparagus dan Keju dengan Peterseli yang ramah ginjal untuk makan malam, sarapan, atau brunch.","4","1 crepe",
["12 batang asparagus","4 ons keju krim","1 ikat peterseli","1 sendok teh air lemon","1/2 sendok teh lada hitam","1/3 cangkir tepung terigu serbaguna","1/2 cangkir air","1/4 cangkir krim","1 butir telur besar","2 putih telur besar","4 sendok makan mentega"],
["Kukus asparagus selama 6 sampai 8 menit.","Haluskan keju krim dengan peterseli, air lemon, dan rempah untuk membuat saus krim hijau. Sesuaikan rasa. Sisihkan.","Untuk membuat crepe, campurkan tepung, air, telur, putih telur, dan 2 sendok makan mentega leleh; kocok hingga menjadi adonan halus.","Lelehkan 1/2 sendok makan mentega dalam wajan (wajan crepe atau wajan tumis 8 sampai 10 inci). Tambahkan 1/3 cangkir adonan crepe dan putar wajan untuk meratakan adonan. Masak hingga berbuih dan tepinya mulai kecokelatan. Balik dan masak sebentar di sisi lainnya. Dinginkan di atas piring. Ulangi dengan sisa mentega dan adonan untuk membuat 4 crepe.","Oleskan isian keju krim pada crepe. Bagi batang asparagus secara merata di ujung setiap crepe lalu gulung dengan kencang.","Bungkus dengan foil dan dinginkan di lemari es selama satu jam. Potong crepe yang sudah dingin menjadi 3 sampai 4 bagian dengan pisau tajam sebelum disajikan."],
["Untuk hidangan utama yang lebih tinggi protein, isi crepe dengan udang sebagai ganti asparagus. Kupas udang, tumis dalam minyak zaitun, biarkan dingin, lalu gulung dalam crepe."],
["1/2 daging","1/2 susu","1 sayuran, kalium sedang","4 lemak"]))
P.append(R(3690,"Salad Kentang Piknik","Salad Kentang Piknik adalah hidangan ramah ginjal yang pantas hadir di semua piknik atau acara kumpul di luar ruangan Anda. Pasien cuci darah perlu merebus atau merendam kentang untuk menurunkan kandungan kalium.","8","1/2 cangkir",
["3 butir telur besar","3 kentang sedang","1 batang seledri","1 bawang bombai kecil","1/2 paprika merah","3/4 cangkir mayones rendah lemak dengan minyak zaitun","3 sendok makan cuka sari apel","1 sendok teh mustard Dijon","1/2 sendok teh lada hitam"],
["Rebus telur hingga matang keras.","Untuk mengurangi kalium pada kentang, kupas kentang, potong kecil-kecil, tutup dengan air, dan didihkan. Buang airnya dan tambahkan air baru. (Lewati bagian ini jika diet rendah kalium tidak diperlukan.) Rebus kentang hingga empuk tetapi masih kenyal saat ditusuk dengan garpu.","Sementara kentang dimasak, cincang halus seledri, bawang bombai, dan paprika. Kupas dan cincang telur rebus.","Tiriskan kentang dan letakkan dalam mangkuk. Tambahkan sayuran dan telur cincang. Jangan diaduk.","Campurkan bahan-bahan dressing salad; tambahkan ke kentang dan aduk perlahan.","Tutup dan dinginkan hingga siap disajikan."],
["Pasien cuci darah dengan diet rendah kalium perlu merebus kentang dua kali untuk menurunkan kandungan kalium. Lewati langkah #2 jika Anda tidak menjalani diet rendah kalium.","Jika mayones biasa digunakan sebagai pengganti mayones rendah lemak, lemak meningkat menjadi 24 gram per porsi. Lakukan perubahan ini jika Anda membutuhkan kalori tambahan.","Gunakan paprika hijau atau kuning jika diinginkan, atau cobalah cabai jalapeño untuk cita rasa pedas."],
["1/2 pati","1 sayuran, kalium sedang","2 lemak"]))
P.append(R(3692,"Crisp Blueberry Persik","Crisp Blueberry Persik menampilkan blueberry yang lezat, ramah ginjal, dan kaya antioksidan, bersama persik yang nikmat, semuanya hangat dan lembut di bawah remahan manis. Begitu lezatnya sehingga keluarga Anda tidak akan menyangka hidangan ini berasal dari buku masak untuk pasien cuci darah.","10","1/10 resep",
["7 persik sedang","1 cangkir blueberry","1/4 cangkir gula pasir","1 sendok makan air lemon","3/4 cangkir tepung terigu serbaguna","3/4 cangkir gula merah padat","1/2 cangkir mentega"],
["Panaskan oven terlebih dahulu hingga 375° F.","Buang biji persik dan iris setebal 3/4″.","Semprot loyang 12″ x 9″ dengan semprotan masak. Tata irisan persik dan blueberry dalam loyang.","Taburkan gula dan air lemon di atas buah.","Campurkan tepung dan gula merah dalam mangkuk. Gunakan dua pisau atau pastry blender, potong mentega ke dalam campuran tepung dan gula hingga bertekstur remah. Taburkan remahan di atas buah.","Panggang pada suhu tersebut selama 45 menit atau lebih lama hingga buah lunak dan remahan kecokelatan.","Sajikan hangat atau pada suhu ruang."],
["Siapkan crisp dan masukkan ke oven tepat sebelum makan malam untuk pencuci mulut buah yang hangat. Tambahkan satu sendok krim kocok jika diinginkan.","Gunakan 4 cangkir irisan persik kalengan yang sudah ditiriskan jika persik segar sedang tidak musim."],
["1 pati","1 buah, kalium sedang","2 lemak"]))
P.append(R(3693,"Salad Orzo Musim Gugur","Rayakan musim gugur dengan Salad Orzo Musim Gugur, resep 4 langkah yang mudah dan bisa disiapkan sebelumnya. Rendah natrium, kalium, dan fosfor, sangat cocok untuk diet ginjal.","4","1/2 cangkir",
["3/4 cangkir orzo","1 apel sedang","1 sendok makan basil segar","2 sendok makan minyak zaitun extra-virgin","2 sendok makan air lemon segar","1/4 sendok teh lada hitam yang baru digiling","2 sendok makan almond iris yang sudah diblansir"],
["Masak orzo sesuai petunjuk kemasan, tanpa garam.","Buang bagian tengah apel dan potong dadu. Cincang basil.","Dalam mangkuk sedang, masukkan semua bahan kecuali almond. Aduk hingga tercampur rata.","Pindahkan campuran ke piring saji dan dinginkan di lemari es selama 30 menit. Taburi dengan almond sebelum disajikan."],
["Tiga perempat cangkir orzo menghasilkan 2 cangkir setelah dimasak.","Apel Fuji, gala, dan red delicious sangat enak dalam salad ini."],
["1-1/2 pati","1/2 buah, kalium rendah","1-1/2 lemak"]))
P.append(R(3695,"Ikan Trout Panggang Oven atau Bakar","North Carolina dikenal dengan ikan trout pelangi, sehingga ahli gizi DaVita, Barb, menyediakan dua resep sehat dan ramah ginjal untuk Trout Panggang dan Bakar.","8","3 ons",
["2 pon fillet ikan trout pelangi","1 sendok makan minyak goreng","1/2 sendok teh garam","1 sendok teh lada lemon bebas garam","1/2 sendok teh paprika"],
["(Panggang Oven)","Panaskan oven terlebih dahulu hingga 350° F.","Cuci dan keringkan fillet. Olesi tipis dengan minyak.","Di atas loyang besar, letakkan fillet dengan sisi kulit menghadap ke bawah.","Campurkan bumbu dalam mangkuk kecil. Taburkan merata di atas fillet.","Panggang tanpa ditutup selama 10 sampai 15 menit atau hingga fillet trout mudah terpisah dengan garpu.","(Bakar)","Panaskan panggangan dengan api besar.","Semprot atau olesi sisi daging fillet trout tipis-tipis dengan minyak. Campurkan bumbu dalam mangkuk kecil. Taburkan merata di atas fillet.","Letakkan trout langsung di atas panggangan, sisi daging menghadap ke bawah. Masak selama 4 menit. Semprot atau olesi kulit tipis-tipis dengan minyak. Balik fillet dan masak hingga ikan mudah terpisah dengan garpu, sekitar 3 sampai 5 menit."],
["Untuk bumbu tambahan, cobalah menambahkan cabai cayenne.","Jika Anda menjalani diet rendah protein, sesuaikan ukuran porsi dengan rencana makan Anda."],
["3 daging"]))
P.append(R(3699,"Muffin Cokelat Selai Kacang","Jika Anda pencinta selai kacang dan cokelat, cobalah kombinasi lezat ini dalam muffin tanpa tepung yang dibuat oleh ahli gizi ginjal DaVita, Alissa dari Nebraska.","16","1 muffin",
["1/2 cangkir mentega","1/2 cangkir madu","1/2 cangkir bubuk kakao tanpa pemanis","3/4 cangkir selai kacang halus","4 butir telur besar","1/2 sendok teh soda kue","3/4 cangkir keping cokelat"],
["Panaskan oven terlebih dahulu hingga 350° F. Alasi cetakan muffin dengan cup kertas.","Lelehkan mentega dan madu bersama-sama. Kocok bubuk kakao dan selai kacang hingga halus.","Kocok telur dan soda kue. Campurkan keping cokelat. Tuang merata ke dalam cetakan muffin.","Panggang selama 18-22 menit atau hingga tusuk gigi yang ditusukkan ke tengah keluar bersih."],
["Jika diinginkan, gunakan selai almond sebagai pengganti selai kacang. Selai almond mengandung fosfor 24 mg lebih banyak dan kalium 16 mg lebih banyak per porsi daripada selai kacang.","Jika lebih suka, gunakan selai kacang rendah lemak. Perubahan ini akan menambah sekitar 4 gram karbohidrat per porsi.","Cokelat dan selai kacang tinggi kalium dan fosfor. Rahasia untuk memasukkannya dalam diet ginjal adalah porsinya–1 muffin kecil. Tanyakan kepada ahli gizi Anda apakah Anda memerlukan pengikat fosfat dengan muffin ini."],
["1 daging","2 lemak","1 kalori tinggi"]))
P.append(R(3701,"Makaroni dan Keju Aman untuk Ginjal","Makaroni dan Keju Aman untuk Ginjal adalah cara ramah ginjal untuk memenuhi keinginan Anda akan mac and cheese.","4","1/2 cangkir",
["1 cangkir pasta siku, mentah","1 botol olesan keju pimento Kraft® yang dibuat dengan keju krim, 5 ons","4 ons cabai hijau potong dadu kalengan Ortega®","1/4 sendok teh lada hitam"],
["Bilas dan tiriskan cabai hijau.","Masak mi dalam air mendidih tanpa garam atau mentega hingga mi al dente.","Tiriskan mi. Selagi mi masih panas, tambahkan olesan keju pimento dan cabai.","Aduk hingga olesan keju meleleh ke dalam mi.","Sajikan panas. Tambahkan lada di meja makan sesuai selera, jika diinginkan."],
["Pasta siku, cangkang, atau pita adalah pilihan yang bagus untuk resep ini.","Untuk variasi lebih tinggi protein, tambahkan daging sapi giling yang sudah dimasak dan ditiriskan.","Sebagian besar olesan keju sangat tinggi natrium dan fosfor. Olesan pimento dalam resep ini dibuat dengan keju krim, bukan keju olahan. (Carilah logo keju krim merek Philadelphia® pada label). Inilah yang menjaga kandungan natrium dan fosfor cukup rendah untuk diet ginjal. Hindari olesan dalam botol atau kaleng yang dibuat dengan keju olahan."],
["1 pati","1 lemak","1/2 susu"]))
P.append(R(3703,"Apel Kayu Manis Microwave Cepat","Perluas repertoar kuliner Anda dengan ide baru untuk pencuci mulut. Ahli gizi DaVita, Lynn dari Maryland, mengatakan Anda dapat membuat hidangan apa pun lebih baik dengan resep Apel Kayu Manis Microwave Cepat yang ramah ginjal miliknya.","2","1 apel",
["2 apel sedang","4 sendok teh madu","1/8 sendok teh pala","1/4 sendok teh kayu manis","1/2 cangkir topping krim kocok susu Reddi-Wip®"],
["Cuci dan buang bagian tengah apel. Kupas 1-2 inci kulit dari bagian atas apel.","Letakkan apel dalam mangkuk tinggi yang aman untuk microwave.","Tuangkan madu ke bagian tengah apel yang sudah dilubangi.","Tambahkan pala dan kayu manis.","Tutup mangkuk dengan penutup yang aman untuk microwave. Panaskan dengan daya tinggi selama sekitar 6 menit.","Sajikan segera, dengan topping krim kocok."],
["Microwave kecil membutuhkan 6 menit untuk memasak satu apel sedang. Waktu memasak bervariasi tergantung ukuran apel dan microwave. Apel matang jika mudah dipotong.","Hindari menutup makanan dengan plastik pembungkus saat memanaskan di microwave karena kemungkinan makanan terkontaminasi racun dari plastik.","Kurangi porsi menjadi 1/2 apel untuk pencuci mulut dengan karbohidrat lebih rendah."],
["1 buah","1 lemak","1 kalori tinggi"]))
P.append(R(3706,"Steak Flank","Steak Flank adalah resep terinspirasi koki dari Chef Frank Bonanno, pemilik 11 restoran di Denver dan pembawa acara \"Chef Driven\", serial PBS yang menampilkan kuliner Colorado. Chef Bonanno dan DaVita bekerja sama menciptakan resep dan video ramah ginjal untuk seri video DaVita Eats: Chef Tips.","3","3 ons",
["2 sendok makan minyak zaitun","10 ons steak flank","1/2 sendok teh lada hitam kasar","1/4 sendok teh paprika"],
["Panaskan wajan tumis dengan api besar hingga panas.","Tambahkan minyak zaitun ke dalam wajan.","Bumbui steak dengan lada hitam dan paprika.","Masukkan steak ke dalam wajan panas dan sangrai dengan api besar selama 4 menit di setiap sisi.","Angkat steak dari wajan dan diamkan selama 2 sampai 3 menit.","Iris miring dan sajikan."],
["Diamkan steak sebelum langsung memotongnya. Ini membuat cita rasanya meresap dengan baik.","Sesuaikan porsi dengan rencana makan Anda.","Resep ini ditampilkan dalam seri video DaVita Eats: Chef Tips."],
["3 daging","1 lemak"]))
P.append(R(3708,"Camilan Campur Cran-Apel Kayu Manis","Satu atau dua genggam camilan campur dapat memuaskan keinginan akan camilan renyah yang manis dan gurih. Ahli gizi DaVita, Mary, membagikan resep ramah ginjalnya untuk Camilan Campur Cran-Apel Kayu Manis.","12","3/4 cangkir",
["1 cangkir apel kering","2 cangkir sereal Corn Chex","2 cangkir sereal Rice Chex","2 cangkir sereal Shredded Wheat Bite-size","3 cangkir sereal Cinnamon Chex","1 cangkir cranberry kering, manis","1/4 cangkir putih telur cair","1/2 cangkir gula","2 sendok makan jus apel","1 sendok teh kayu manis","1 sendok makan biji wijen"],
["Panaskan oven terlebih dahulu hingga 300° F. Semprot loyang kue persegi panjang besar (9″ x 13″ atau lebih besar) dengan semprotan masak antilengket.","Potong dadu apel kering.","Dalam mangkuk besar, campurkan sereal dan buah kering; sisihkan.","Dalam mangkuk sedang, kocok putih telur, gula, jus apel, dan kayu manis dengan whisk atau mixer tangan hingga berbusa.","Tuang campuran telur di atas sereal dalam mangkuk, aduk hingga terlapisi merata.","Taburi dengan biji wijen.","Ratakan campuran ke dalam loyang dan panggang selama 45 menit, aduk setiap 15 menit, hingga sereal berwarna cokelat muda dan renyah.","Dinginkan sepenuhnya. Simpan dalam wadah kedap udara."],
["Mary menggunakan produk putih telur cair pasteurisasi All Whites®. Anda dapat menggantinya dengan 1/4 cangkir putih telur segar.","Ganti gula dengan pemanis rendah karbohidrat pilihan Anda untuk mengurangi karbohidrat menjadi 38 gram per porsi. Jika Anda menderita diabetes, pertimbangkan untuk menyesuaikan porsi menjadi 1/2 cangkir selain perubahan ini."],
["1 pati","1 buah, kalium rendah","1 kalori tinggi"]))
P.append(R(3710,"Arroz con Gandules (Nasi dengan Kacang Gude)","Arroz con Gandules adalah hidangan nasi yang lezat dan ramah ginjal, sehat, dan berwarna meriah — hidangan sempurna untuk keluarga atau untuk disajikan di pesta makan malam.","8","1/2 cangkir",
["2 sendok teh minyak zaitun","2 sendok teh Sofrito","1 sendok teh bubuk annatto Bijol®","1 sendok makan pasta tomat","1 siung bawang putih","1 sendok teh oregano kering","1/2 kubus kaldu rasa ayam","1 cangkir kacang gude kalengan","2 cangkir beras butir panjang, mentah"],
["Tiriskan dan bilas kacang gude. Cincang halus bawang putih.","Panaskan 2 sendok teh minyak dalam panci besar.","Tambahkan Sofrito, bubuk Bijol®, pasta tomat, bawang putih, oregano, kubus kaldu, dan kacang gude.","Tumis sambil diaduk selama sekitar 3 sampai 4 menit untuk mengunci sari.","Dalam panci besar, masak nasi mengikuti petunjuk pada kemasan, tanpa garam.","Campurkan nasi dengan bahan-bahan dalam panci besar dan sajikan."],
["Lihat resep Sofrito di DaVita.com.","Untuk protein lebih banyak, tambahkan satu cangkir ayam cincang. Menambah 4 gram protein per porsi. Gunakan setengah ayam panggang rotisserie tanpa kulit dan tulang untuk menghemat waktu.","Bijol®, nama merek untuk bubuk achiote atau annatto, memberikan warna kuning-oranye pada nasi. Ini adalah pengganti saffron. Jika tidak tersedia, gunakan paprika dan kunyit dalam jumlah yang sama.","Kacang gude beku atau kering yang sudah dimasak dapat digunakan sebagai pengganti kacang kalengan."],
["2-1/2 pati","1/2 sayuran, kalium sedang"]))
P.append(R(3711,"Nasi Pilaf","Ahli gizi ginjal DaVita, Mary Anne dari California, membagikan resep Nasi Pilafnya. Hidangan pendamping ramah ginjal ini jauh lebih rendah natrium daripada campuran siap beli karena Anda membuatnya sendiri di rumah.","8","1/2 cangkir",
["1/4 cangkir bawang bombai","1/2 cangkir seledri","1 sendok makan peterseli segar","1 cangkir vermicelli, dipatahkan menjadi potongan kecil","1/4 cangkir margarin","1 cangkir beras putih, mentah","1-1/2 cangkir kaldu ayam rendah natrium","1-1/2 cangkir air"],
["Cincang bawang bombai, seledri, dan peterseli. Patahkan vermicelli menjadi potongan kecil.","Lelehkan margarin dalam wajan yang memiliki penutup.","Tumis bawang bombai dan seledri selama 1 menit.","Tambahkan beras dan vermicelli lalu aduk selama 30 detik.","Tambahkan kaldu ayam, air, dan peterseli. Didihkan.","Tutup dan kecilkan api, masak sekitar 15 menit hingga semua cairan terserap."],
["Pasta angel hair dapat digunakan sebagai pengganti vermicelli dalam resep ini."],
["2 pati","1 lemak"]))
P.append(R(3712,"Omelet Jamur dan Paprika Merah","Jika Anda mencari sarapan yang mengenyangkan dan lezat, cobalah resep ramah ginjal, Omelet Jamur & Paprika Merah.","2","1/2 omelet",
["1/2 cangkir potongan jamur mentah","2 sendok makan bawang bombai","1/4 cangkir paprika merah manis kalengan","2 sendok teh mentega","3 butir telur besar","1 sendok teh saus Worcestershire","2 sendok makan keju krim kocok","1/4 sendok teh lada hitam"],
["Potong dadu jamur, bawang bombai, dan paprika merah.","Lelehkan 1 sendok teh mentega dalam wajan dengan api sedang. Masukkan jamur dan bawang bombai; tumis 5 menit hingga bawang bombai empuk. Masukkan paprika merah potong dadu. Angkat sayuran dari wajan dan sisihkan.","Lelehkan sisa satu sendok teh mentega dalam wajan. Kocok telur dengan saus Worcestershire dan masak dengan api sedang. Masak omelet secara merata dengan menggoyangkan wajan dan mengangkat tepinya perlahan agar telur mentah mengalir ke bawah telur yang sudah matang.","Ketika telur sudah setengah matang, taruh campuran sayuran di atasnya. Letakkan sesendok keju krim kocok di atas sayuran. Lanjutkan memasak hingga telur matang.","Angkat wajan dari api dan lipat omelet menjadi dua. Taburi dengan lada. Bagi menjadi dua porsi dan sajikan."],
["Bawang bombai yang ditumis akan tampak bening tetapi tidak cokelat saat matang.","Bandingkan kandungan natrium pada paprika merah dalam botol atau kaleng.","Kurangi lemak dan kolesterol dengan menggunakan semprotan masak antilengket atau wajan antilengket, margarin bebas lemak trans sebagai pengganti mentega, dan pengganti telur cair rendah kolesterol sebagai pengganti telur utuh."],
["1-1/2 daging","2 lemak","1/2 sayuran, kalium sedang"]))
save(4,P)
